  "Die rote Linie zeigt, wie viel du in jedem der letzten {n} Monate ausgegeben hast. Die gestrichelte Linie ist dein Durchschnitt. Ein Punkt über der gestrichelten Linie heißt: in dem Monat mehr ausgegeben als sonst. Klick auf einen Monat, um ihn anzusehen.",
  "Pro Monat: Einnahmen minus Ausgaben. **Grün** = es ist Geld übrig geblieben. **Rot** = du hast mehr ausgegeben als reinkam. Die Zahl über dem Balken ist der Betrag in Euro.",
  "Jede Zeile ist ein Bereich, z. B. Lebensmittel. Rechts steht, was du diesen Monat dafür ausgegeben hast. Die Prozentzahl vergleicht mit deinem Schnitt der {n} Monate davor: **rot** = mehr als sonst, **grün** = weniger.",
  "Pro Monat zwei Balken: **rot** = {n} **grau** = {n} Ist der rote Balken kleiner als der graue, hast du in dem Monat weniger ausgegeben als im Vorjahr. Fahr mit der Maus über einen Monat für die genauen Beträge.",
  "Grobe Schätzung deiner Einkommensteuer für das ganze Jahr, berechnet aus deinen Buchungen. **Plus** = du musst voraussichtlich nachzahlen, **Minus** = du bekommst etwas zurück, **± {n} €** = weder noch. „Zu versteuern“ ist dein Einkommen nach Abzügen.",
